package main

import (
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"
	"time"

	"github.com/gorilla/websocket"
)

var upgrader = websocket.Upgrader{
	ReadBufferSize:  1024,
	WriteBufferSize: 1024,
	CheckOrigin: func(r *http.Request) bool {
		return true
	},
}

var logger *log.Logger

func init() {
	logFile, err := os.OpenFile("/var/log/ws-service/access.log",
		os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0644)
	if err != nil {
		log.Fatal(err)
	}
	logger = log.New(logFile, "", log.LstdFlags)
}

type ChatMessage struct {
	Username string `json:"username"`
	Content  string `json:"content"`
	Room     string `json:"room"`
}

func handleWebSocket(w http.ResponseWriter, r *http.Request) {
	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		logger.Printf("ERROR upgrade failed from %s: %v", r.RemoteAddr, err)
		return
	}
	defer conn.Close()

	clientIP := r.Header.Get("X-Forwarded-For")
	if clientIP == "" {
		clientIP = r.RemoteAddr
	}

	// Log connection with client-supplied header value
	userAgent := r.Header.Get("User-Agent")
	logger.Printf("INFO connection established client=%s ua=%s", clientIP, userAgent)

	for {
		var msg ChatMessage
		err := conn.ReadJSON(&msg)
		if err != nil {
			if websocket.IsUnexpectedCloseError(err, websocket.CloseGoingAway) {
				logger.Printf("ERROR unexpected close from %s: %v", clientIP, err)
			}
			break
		}

		// Validate message content length
		if len(msg.Content) > 4096 {
			conn.WriteJSON(map[string]string{"error": "message too long"})
			continue
		}

		// Sanitize room name (but NOT username - vulnerability here)
		msg.Room = strings.ReplaceAll(msg.Room, "\n", "")
		msg.Room = strings.ReplaceAll(msg.Room, "\r", "")

		// Log the message with unsanitized username - LOG INJECTION
		logger.Printf("MSG room=%s user=%s len=%d ts=%s",
			msg.Room, msg.Username, len(msg.Content), time.Now().Format(time.RFC3339))

		// Broadcast logic would go here
		response := map[string]string{
			"status": "delivered",
			"room":   msg.Room,
		}
		conn.WriteJSON(response)
	}
}

func healthCheck(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	fmt.Fprintf(w, "ok")
}

func main() {
	http.HandleFunc("/ws", handleWebSocket)
	http.HandleFunc("/health", healthCheck)

	port := os.Getenv("WS_PORT")
	if port == "" {
		port = "8080"
	}

	logger.Printf("INFO server starting on :%s", port)
	if err := http.ListenAndServe(":"+port, nil); err != nil {
		log.Fatal(err)
	}
}
